using System.Linq;
using System.Threading;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace YFex.Rules.Generator;

/// <summary>
/// Turns a permission named in a Rules attribute (<c>[DecisionTable(PublishPermission = …)]</c>,
/// <c>[Then(…, ApprovalPermission = …)]</c>) into the C# expression of a typed <c>Permission</c> (authorization-consolidation ⚑Z2).
/// </summary>
/// <remarks>
/// <c>Catalog.Ids.X</c> constants are generated by the Authorization generator. When the catalog lives in the same compilation,
/// its <c>Ids</c> class does not exist while this generator runs, so the argument has no constant value. The catalog type and the
/// member are then read from the syntax, and the expression is the catalog's typed accessor (<c>global::Ns.Catalog.X</c>). An
/// argument that cannot be resolved either way is reported (YFR0108) instead of silently dropping the permission.
/// </remarks>
internal static class PermissionArguments
{
    private const string PermissionAttribute = "YFex.Authorization.Public.PermissionAttribute";
    private const string CatalogAttribute = "YFex.Authorization.Public.PermissionCatalogAttribute";
    private const string PermissionType = "global::YFex.Authorization.Public.Permission";

    /// <summary>The expression, or null when the argument is absent. <paramref name="unresolved"/> = present but not resolvable.</summary>
    public static string? Expression(AttributeData attribute, string name, SemanticModel model, CancellationToken cancellationToken,
        out bool unresolved)
    {
        unresolved = false;
        foreach (var argument in attribute.NamedArguments)
            if (argument.Key == name && argument.Value.Value is string id)
                return PermissionType + ".Parse(" + Names.Literal(id) + ")";

        if (attribute.ApplicationSyntaxReference?.GetSyntax(cancellationToken) is not AttributeSyntax syntax || syntax.ArgumentList is null)
            return null;
        var written = syntax.ArgumentList.Arguments.FirstOrDefault(a => a.NameEquals?.Name.Identifier.ValueText == name);
        if (written is null) return null;
        if (written.Expression is LiteralExpressionSyntax { Token.Value: null }) return null;     // = null

        var semantic = syntax.SyntaxTree == model.SyntaxTree ? model : model.Compilation.GetSemanticModel(syntax.SyntaxTree);
        if (written.Expression is MemberAccessExpressionSyntax access
            && access.Expression is MemberAccessExpressionSyntax ids && ids.Name.Identifier.ValueText == "Ids"
            && semantic.GetSymbolInfo(ids.Expression, cancellationToken).Symbol is INamedTypeSymbol catalog
            && catalog.GetAttributes().Any(a => a.AttributeClass?.ToDisplayString() == CatalogAttribute))
        {
            var member = access.Name.Identifier.ValueText;
            foreach (var candidate in catalog.GetMembers(member))
                if (candidate is IPropertySymbol property
                    && property.GetAttributes().Any(a => a.AttributeClass?.ToDisplayString() == PermissionAttribute))
                    return Names.Of(catalog) + "." + property.Name;
        }
        unresolved = true;
        return null;
    }
}
